const v = context.vars.vitals;
const pats = [[/SpO2 (\d+)%/g, 'spo2'], [/\bHR (\d+)/g, 'hr'], [/\bRR (\d+)/g, 'rr'], [/\bBP (\d+\/\d+)/g, 'bp'], [/\bT (\d+(?:\.\d)?) ?°C/g, 'temp']];
for (const [re, k] of pats) { let m; while ((m = re.exec(output))) if (String(m[1]) !== String(v[k])) return false; }
return true;

const dx = (output.match(/^\d+\. /gm) || []).length;
const ev = (output.match(/^\s*Evidence: /gm) || []).length;
return dx > 0 && dx === ev;
